export type ParsedCreateTwinInstruction<
  TProgram extends string = typeof LVRT_TWINS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    authority: TAccountMetas[1];
    config: TAccountMetas[2];
    twin: TAccountMetas[3];
    /**
     * Owns the engine margin account and signs for it; a system account so
     * it can pay the engine's rent.
     */
    twinSigner: TAccountMetas[4];
    priceState: TAccountMetas[5];
    engineMarket: TAccountMetas[6];
    mint: TAccountMetas[7];
    usdcMint: TAccountMetas[8];
    usdcBuffer: TAccountMetas[9];
    engineMargin: TAccountMetas[10];
    engineProgram: TAccountMetas[11];
    twinTokenProgram: TAccountMetas[12];
    usdcTokenProgram: TAccountMetas[13];
    systemProgram: TAccountMetas[14];
  };
  data: CreateTwinInstructionData;
};

export function parseCreateTwinInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCreateTwinInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 15,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      authority: getNextAccount(),
      config: getNextAccount(),
      twin: getNextAccount(),
      twinSigner: getNextAccount(),
      priceState: getNextAccount(),
      engineMarket: getNextAccount(),
      mint: getNextAccount(),
      usdcMint: getNextAccount(),
      usdcBuffer: getNextAccount(),
      engineMargin: getNextAccount(),
      engineProgram: getNextAccount(),
      twinTokenProgram: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getCreateTwinInstructionDataDecoder().decode(instruction.data),
  };
}
